import { a as scanDetailedSync, i as generateSync, n as generateDySync, o as scanSync, r as generateSvgSync, t as generateDySvgSync } from "./sync-ClHLLyfY.js";
//#region src/browser-worker.ts
const workerScope = globalThis;
const serializeError = (error) => {
	if (error instanceof Error) return {
		message: error.message,
		name: error.name,
		stack: error.stack
	};
	return { message: String(error) };
};
const postSuccess = (id, value) => {
	if (value instanceof Uint8Array) {
		workerScope.postMessage({
			id,
			ok: true,
			value
		}, [value.buffer]);
		return;
	}
	workerScope.postMessage({
		id,
		ok: true,
		value
	});
};
workerScope.addEventListener("message", (event) => {
	const request = event.data;
	try {
		switch (request.method) {
			case "generate":
				postSuccess(request.id, generateSync(request.options, request.format, request.encoding));
				break;
			case "generateSvg":
				postSuccess(request.id, generateSvgSync(request.options));
				break;
			case "generateDy":
				postSuccess(request.id, generateDySync(request.options, request.format, request.encoding));
				break;
			case "generateDySvg":
				postSuccess(request.id, generateDySvgSync(request.options));
				break;
			case "scan":
				postSuccess(request.id, scanSync(request.imageData));
				break;
			case "scanDetailed": postSuccess(request.id, scanDetailedSync(request.imageData));
		}
	} catch (error) {
		workerScope.postMessage({
			id: request.id,
			ok: false,
			error: serializeError(error)
		});
	}
});
workerScope.postMessage({ type: "ready" });
//#endregion
